import{c as e,S as a,j as s,m as i}from"./chunks/framework.DBSVVeOL.js";const u=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks.md","filePath":"benchmarks.md","lastUpdated":null}'),r={name:"benchmarks.md"};function l(n,t,d,o,c,h){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="Benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#Benchmarks" aria-label="Permalink to &quot;Benchmarks {#Benchmarks}&quot;">​</a></h1><p>The comparison table below is generated from local benchmark JSON artifacts. Run it from the repository root with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --justfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmarks/justfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> with-server</span></span></code></pre></div><p>The default run starts <code>nats:2.11</code>, runs seven trials each for Natter.jl, Python <code>nats.py</code>, Rust <code>nats.rs</code>, and Go <code>nats.go</code>, writes raw and aggregate artifacts under <code>benchmarks/results/</code>, aggregates each metric by median, and updates this page and the README. Warmup work runs before each timed region, GC-capable runners collect before timing starts, and fast timed regions repeat whole rounds until the configured minimum duration is reached, so startup, package loading, compilation/build time, dependency downloads, and benchmark warmup are not included in the reported timings. The cross-client callback row uses Natter.jl&#39;s inline callback mode; the Natter-only report includes both inline and task-backed callback rows.</p><p>The default minimum timed-region duration is five seconds. Set <code>NATTER_BENCH_MIN_SECONDS</code> to a larger value when comparing small performance changes or running on a noisy host.</p><p>&lt;!– NATTER_BENCHMARK_TABLE_START –&gt; Benchmark parameters: at least <code>200000</code> messages or <code>20000</code> requests per timed round, <code>64</code> byte payload, <code>7</code> trials per client, minimum timed-region duration <code>5.0</code> seconds, URL <code>nats://127.0.0.1:4222</code>. Timed regions exclude startup, package loading, compilation/build time, dependency downloads, and benchmark warmup.</p><p>Benchmarks use each client&#39;s common high-level publish, subscribe, request, and flush APIs. Fast timed regions repeat whole rounds until the minimum duration is reached, then report total operations per second. GC-capable runners collect before the timed region to avoid carrying setup and warmup garbage into the measured window. Batch publish reuses stable subject and payload values in every client: Natter.jl uses <code>prepare_publish</code>, Rust uses prebuilt <code>Subject</code> and <code>Bytes</code>, and Go/Python reuse their subject string and payload buffer. Natter.jl callback dispatch uses <code>callback_mode=:inline</code> in this comparison; the Natter-only report also includes task-backed callback rows. The table reports median-of-<code>7</code> results for each metric.</p><p>Flush semantics differ by client: Natter.jl, Go, and Python flush with a server PING/PONG round trip; Rust <code>async-nats</code> flush waits for the client writer/socket flush. Treat the Rust publish-plus-flush-each value as client-flush throughput, while request/reply rows are server round trips for all clients.</p><p>Optimization modes: Natter.jl runs with <code>julia --startup-file=no -O3 --check-bounds=no -C native</code>; Go runs from an explicit <code>go build -trimpath</code> binary; Rust runs from <code>cargo build --release</code>; the NATS server uses the official <code>nats:2.11</code> image.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Metric</th><th style="text-align:right;">Natter.jl</th><th style="text-align:right;">Go nats.go</th><th style="text-align:right;">Rust nats.rs</th><th style="text-align:right;">Python nats.py</th></tr></thead><tbody><tr><td style="text-align:left;">Publish batch buffered msg/s</td><td style="text-align:right;">4,677,813</td><td style="text-align:right;">4,007,526</td><td style="text-align:right;">4,854,196</td><td style="text-align:right;">377,902</td></tr><tr><td style="text-align:left;">Publish + flush each msg/s</td><td style="text-align:right;">32,406</td><td style="text-align:right;">24,445</td><td style="text-align:right;">134,627</td><td style="text-align:right;">23,976</td></tr><tr><td style="text-align:left;">Callback dispatch inline batch msg/s</td><td style="text-align:right;">2,536,285</td><td style="text-align:right;">2,436,326</td><td style="text-align:right;">2,901,149</td><td style="text-align:right;">193,461</td></tr><tr><td style="text-align:left;">Request/reply req/s</td><td style="text-align:right;">15,757</td><td style="text-align:right;">10,167</td><td style="text-align:right;">9,101</td><td style="text-align:right;">9,694</td></tr><tr><td style="text-align:left;">Request p50 latency ms</td><td style="text-align:right;">0.046</td><td style="text-align:right;">0.057</td><td style="text-align:right;">0.065</td><td style="text-align:right;">0.092</td></tr><tr><td style="text-align:left;">Request p95 latency ms</td><td style="text-align:right;">0.135</td><td style="text-align:right;">0.292</td><td style="text-align:right;">0.293</td><td style="text-align:right;">0.161</td></tr></tbody></table><p>Generated from benchmark JSON artifacts at <code>2026-05-21T00:51:20.552</code>. &lt;!– NATTER_BENCHMARK_TABLE_END –&gt;</p>',11)])])}const p=e(r,[["render",l]]);export{u as __pageData,p as default};
